import{_ as t,o as a,c as o,ae as r}from"./chunks/framework.Bs_1Tt6f.js";const g=JSON.parse('{"title":"Settings & Data Backup","description":"","frontmatter":{},"headers":[],"relativePath":"docs/settings-and-data.md","filePath":"docs/settings-and-data.md"}'),i={name:"docs/settings-and-data.md"};function n(s,e,l,c,d,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="settings-data-backup" tabindex="-1">Settings &amp; Data Backup <a class="header-anchor" href="#settings-data-backup" aria-label="Permalink to &quot;Settings &amp; Data Backup&quot;">​</a></h1><p>The <strong>Settings</strong> view provides essential tools for managing your local data, customizing the application&#39;s display, and defining defaults to speed up your workflow.</p><div class="info custom-block"><p class="custom-block-title">💡 Suggestion for Future Documentation</p><p><em>[Consider inserting a screen recording here showing the process of exporting a JSON backup and subsequently importing it.]</em></p></div><h2 id="data-storage-backup-crucial" tabindex="-1">Data Storage &amp; Backup (Crucial!) <a class="header-anchor" href="#data-storage-backup-crucial" aria-label="Permalink to &quot;Data Storage &amp; Backup (Crucial!)&quot;">​</a></h2><p><strong>CM Transcription Equivalents</strong> stores all your work (manuscripts, regions, polygons, and equivalent mappings) directly in your browser&#39;s local storage. This ensures the app is fast and doesn&#39;t require a constant server connection.</p><p>However, <strong>if you clear your browser cache, you will lose your work!</strong> Therefore, frequent backups are mandatory.</p><h3 id="exporting-your-data" tabindex="-1">Exporting Your Data <a class="header-anchor" href="#exporting-your-data" aria-label="Permalink to &quot;Exporting Your Data&quot;">​</a></h3><ol><li>Navigate to the <strong>Settings</strong> tab.</li><li>In the &quot;Data Backup&quot; section, enter a label for your backup (e.g., &quot;st_gallen_project&quot;).</li><li>Click <strong>Export JSON</strong>. The tool will download a complete snapshot of your workspace to your computer.</li></ol><h3 id="importing-data" tabindex="-1">Importing Data <a class="header-anchor" href="#importing-data" aria-label="Permalink to &quot;Importing Data&quot;">​</a></h3><p>If you switch computers, accidentally clear your cache, or want to collaborate with a colleague:</p><ol><li>Go to <strong>Settings</strong>.</li><li>Click <strong>Import JSON</strong> and select your previously exported file.</li><li>The tool will seamlessly merge the imported data with your current workspace.</li></ol><h3 id="clearing-all-data" tabindex="-1">Clearing All Data <a class="header-anchor" href="#clearing-all-data" aria-label="Permalink to &quot;Clearing All Data&quot;">​</a></h3><p>If you need a fresh start, use the <strong>Remove All Data</strong> button. <strong>Warning:</strong> This action is irreversible. Always export a JSON backup before performing a full reset.</p><h2 id="app-defaults" tabindex="-1">App Defaults <a class="header-anchor" href="#app-defaults" aria-label="Permalink to &quot;App Defaults&quot;">​</a></h2><p>You can customize how the application displays transcription patterns across all views (Equivalents table, Editor, Public view).</p><ul><li><strong>Global Pattern View (Standard)</strong>: Choose how abstract transcription patterns are rendered: <ul><li><strong>Graphic (SVG)</strong>: Renders the pattern using a standard, generalized notation font (if available).</li><li><strong>Arrows (↗/↘)</strong>: Renders the melodic contour using directional arrows (useful for quick visual scanning).</li><li><strong>Text (u/d/e)</strong>: Renders the raw text string indicating melodic movement (up, down, equal).</li></ul></li></ul><h2 id="preferred-custom-ids-auto-fill" tabindex="-1">Preferred Custom IDs (Auto-fill) <a class="header-anchor" href="#preferred-custom-ids-auto-fill" aria-label="Permalink to &quot;Preferred Custom IDs (Auto-fill)&quot;">​</a></h2><p>To drastically speed up the annotation process, you can define <strong>Preferred Custom IDs</strong>.</p><p>If your transcription data frequently uses a specific text string (e.g., <code>*dd</code>) to represent a specific neume shape that you always label as Ref ID <code>Type A</code>, you can configure the tool to automatically recognize this.</p><ol><li>In the <strong>Settings</strong> view, locate the &quot;Preferred Custom IDs&quot; section.</li><li>Enter the exact transcription pattern string (e.g., <code>*dd</code>).</li><li>Enter your desired default Ref ID (e.g., <code>Type A</code>).</li><li>Click <strong>Add Preference</strong>.</li></ol><p>Now, whenever you draw a polygon in the editor and link it to an occurrence that matches the <code>*dd</code> pattern, the tool will <em>automatically</em> fill in the Ref ID as <code>Type A</code>, saving you manual entry time. You can still override it if needed.</p>',21)])])}const h=t(i,[["render",n]]);export{g as __pageData,h as default};
